-- Sample database: E-Commerce
-- GENERATED by app/sample_dbs/generate.py — do not edit by hand

CREATE TABLE categories (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        varchar(80) NOT NULL UNIQUE,
  parent_id   integer REFERENCES categories(id),
  description text
);
CREATE TABLE customers (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name  varchar(50) NOT NULL,
  last_name   varchar(50) NOT NULL,
  email       varchar(120) NOT NULL UNIQUE,
  phone       varchar(20),
  city        varchar(60),
  country     varchar(60) NOT NULL DEFAULT 'Thailand',
  created_at  date NOT NULL
);
CREATE TABLE products (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        varchar(120) NOT NULL,
  category_id integer REFERENCES categories(id),
  price       numeric(10,2) NOT NULL CHECK (price >= 0),
  cost        numeric(10,2) NOT NULL CHECK (cost >= 0),
  stock       integer NOT NULL DEFAULT 0,
  is_active   boolean NOT NULL DEFAULT true,
  created_at  date NOT NULL
);
CREATE TABLE orders (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL REFERENCES customers(id),
  order_date  timestamp NOT NULL,
  status      varchar(20) NOT NULL CHECK (status IN ('pending','paid','shipped','delivered','cancelled')),
  shipping_city varchar(60)
);
CREATE TABLE order_items (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id    integer NOT NULL REFERENCES orders(id),
  product_id  integer NOT NULL REFERENCES products(id),
  quantity    integer NOT NULL CHECK (quantity > 0),
  unit_price  numeric(10,2) NOT NULL,
  discount    numeric(10,2)
);
CREATE TABLE payments (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id     integer NOT NULL REFERENCES orders(id),
  payment_date timestamp NOT NULL,
  amount       numeric(12,2) NOT NULL,
  method       varchar(20) NOT NULL CHECK (method IN ('credit_card','bank_transfer','promptpay','cod'))
);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_order_items_product ON order_items(product_id);
CREATE INDEX idx_payments_order ON payments(order_id);

COMMENT ON TABLE categories IS 'หมวดหมู่สินค้า (มีหมวดย่อยผ่าน parent_id — ใช้ฝึก Self Join / Recursive CTE)';
COMMENT ON COLUMN categories.parent_id IS 'หมวดแม่ (NULL = หมวดระดับบนสุด)';
COMMENT ON TABLE customers IS 'ลูกค้า — บางคนยังไม่เคยสั่งซื้อ, บางคนไม่มี phone/city';
COMMENT ON COLUMN customers.city IS 'เมือง (อาจเป็น NULL และสะกดไม่สม่ำเสมอ เช่น bangkok)';
COMMENT ON TABLE products IS 'สินค้า — บางรายการไม่เคยขาย, บางรายการไม่มีหมวด';
COMMENT ON COLUMN products.cost IS 'ต้นทุนต่อชิ้น (ใช้คำนวณกำไร)';
COMMENT ON TABLE orders IS 'คำสั่งซื้อ (ปี 2024-2025)';
COMMENT ON COLUMN orders.status IS 'pending | paid | shipped | delivered | cancelled';
COMMENT ON TABLE order_items IS 'รายการสินค้าในแต่ละคำสั่งซื้อ';
COMMENT ON COLUMN order_items.unit_price IS 'ราคาต่อชิ้น ณ วันที่สั่ง (อาจต่างจาก products.price ปัจจุบัน)';
COMMENT ON COLUMN order_items.discount IS 'ส่วนลดรวมของรายการ (NULL = ไม่มีส่วนลด)';
COMMENT ON TABLE payments IS 'การชำระเงิน — order ที่ pending/cancelled ไม่มี payment; บาง order ผ่อน 2 งวด';























